"""Helper code that is copied into every Python file generated from Plain.

It formats numbers the Plain way and turns run-time problems into friendly messages.
"""

PRELUDE = '''\
# Generated by the Plain compiler Run with: python3 <this file>
import math
import random as _rng
import sys

sys.setrecursionlimit(10000)
try:
    sys.stdout.reconfigure(encoding="utf-8")
    sys.stdin.reconfigure(encoding="utf-8")
except AttributeError:
    pass


class _PlainError(Exception):
    def __init__(self, message, line=0):
        super().__init__(message)
        self.message = message
        self.line = line


def _fmt(value):
    """Turn any Plain value into text."""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "nothing"
    if isinstance(value, float):
        return "%.15g" % value
    return value


def _add(a, b):
    if isinstance(a, str) or isinstance(b, str):
        return _fmt(a) + _fmt(b)
    return a + b


def _eq(a, b):
    if isinstance(a, (list, float, str, bool)) or a is None:
        if isinstance(a, list):
            return a is b
        return a == b
    return a is b


def _div(a, b, line):
    if b == 0:
        raise _PlainError("Cannot divide by zero.", line)
    return a / b


def _mod(a, b, line):
    if b == 0:
        raise _PlainError("Cannot use mod with zero.", line)
    return math.fmod(a, b)


def _get(items, index, line):
    i = int(index)
    if i < 0 or i >= len(items):
        raise _PlainError("That list position does not exist (the first item is at position 0).", line)
    return items[i]


def _set(items, index, value, line):
    i = int(index)
    if i < 0 or i >= len(items):
        raise _PlainError("That list position does not exist (the first item is at position 0).", line)
    items[i] = value


def _size_or_field(obj, name):
    if isinstance(obj, list):
        return float(len(obj))
    return getattr(obj, name)


def _remove(items, value):
    for i, item in enumerate(items):
        if _eq(item, value):
            del items[i]
            return


def _of(name, fn, obj, line):
    """'name of value': a built-in helper for text and numbers, otherwise a field."""
    if isinstance(obj, (str, float)):
        return fn(obj, line)
    return getattr(obj, "f_" + name)


def _length(text, line):
    return float(len(text))


def _upper(text, line):
    return "".join(c.upper() if "a" <= c <= "z" else c for c in text)


def _lower(text, line):
    return "".join(c.lower() if "A" <= c <= "Z" else c for c in text)


def _round(x, line):
    return float(math.floor(x + 0.5))


def _abs(x, line):
    return abs(x)


def _sqrt(x, line):
    if x < 0:
        raise _PlainError("Cannot take the square root of a negative number.", line)
    return math.sqrt(x)


def _min(a, b, line=0):
    return a if a < b else b


def _max(a, b, line=0):
    return a if a > b else b


def _part(text, start, count, line):
    s, c = int(start), int(count)
    if s < 0 or c < 0:
        raise _PlainError("Text positions and lengths cannot be negative.", line)
    return text[s:s + c]


def _contains(text, piece, line=0):
    return piece in text


def _random(low, high, line):
    a, b = int(low), int(high)
    if a > b:
        raise _PlainError("The first number of 'random' must not be bigger than the second.", line)
    return float(_rng.randint(a, b))


def _remove_at(items, index, line):
    i = int(index)
    if i < 0 or i >= len(items):
        raise _PlainError("That list position does not exist (the first item is at position 0).", line)
    del items[i]


def _input(prompt):
    sys.stdout.write(prompt + " ")
    sys.stdout.flush()
    line = sys.stdin.readline()
    return line.rstrip("\\r\\n")


def _input_number(prompt, line):
    text = _input(prompt)
    if not all(c in "0123456789+-.eE " for c in text):
        raise _PlainError("That is not a number.", line)
    try:
        return float(text.strip(" "))
    except ValueError:
        raise _PlainError("That is not a number.", line)


_FINISHERS = []     # modules add a function here that runs after the program ends (see modules/window)


def _finish():
    """Runs after the program ends (a window stays open until it is closed)."""
    for finisher in _FINISHERS:
        finisher()


def _run(main):
    try:
        main()
        _finish()
    except _PlainError as err:
        where = "Error in line %d: " % err.line if err.line else "Error: "
        print(where + err.message)
        sys.stdout.flush()
        sys.exit(1)
'''

# Added to a program only when the IDE asks to watch values (PLAIN_WATCH=<file>). A background thread
# writes a snapshot of the changed variables a few times per second, so the program itself hardly notices.
WATCH_PRELUDE = """\
import json as _json
import os as _wos
import threading as _wthreading
import time as _wtime

_W = {}
_T = {}
_W_STATE = {"dirty": False, "seq": 0}
_W_PATH = _wos.environ.get("PLAIN_WATCH")


class _Shown(str):
    # a value that was turned into text at the moment it was recorded (lists and things change later)
    pass


def _snap(value):
    if isinstance(value, (list, tuple)) or getattr(value, "__slots__", None):
        return _Shown(_wfmt(value))
    return value


def _wfmt(value, depth=0):
    if isinstance(value, _Shown):
        return str(value)
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "nothing"
    if isinstance(value, float):
        return "%.15g" % value
    if isinstance(value, str):
        text = value if len(value) <= 30 else value[:27] + "..."
        return '"' + text + '"'
    if isinstance(value, list):
        if depth > 1:
            return "list of %d" % len(value)
        shown = ", ".join(_wfmt(v, depth + 1) for v in value[:8])
        return "[" + shown + (", ... (%d)" % len(value) if len(value) > 8 else "") + "]"
    slots = getattr(value, "__slots__", None)
    if slots:
        if depth > 1:
            return type(value).__name__[2:] + "(...)"
        parts = ", ".join("%s: %s" % (n[2:], _wfmt(getattr(value, n), depth + 1)) for n in slots)
        return type(value).__name__[2:] + "(" + parts + ")"
    return str(value)


def _wnote(entry):
    kind = entry[0]
    if kind == "val":
        return entry[1] + _wfmt(entry[2])
    if kind == "call":
        text = entry[1] + "(" + ", ".join(_wfmt(a) for a in entry[2]) + ")"
        return text if entry[3] is None else text + " -> " + _wfmt(entry[3])
    if kind == "params":
        return "takes " + ", ".join("%s = %s" % (n, _wfmt(v)) for n, v in zip(entry[1], entry[2]))
    text = "(" + ", ".join(_wfmt(a) for a in entry[1]) + ")" if entry[1] else ""
    return text if entry[2] is None else (text + " -> " if text else "-> ") + _wfmt(entry[2])


def _wvar(name, value, line):
    _W[name] = (value, line)
    _W_STATE["dirty"] = True


def _watch(name, value, line, shown=_wvar):
    _W[name] = (value, line)
    _T[line] = ("val", "-> ", _snap(value if shown is _wvar else shown))
    _W_STATE["dirty"] = True


def _tr(line, value, prefix="-> "):
    current = _T.get(line)
    if current is None or current[0] != "call":
        _T[line] = ("val", prefix, _snap(value))
        _W_STATE["dirty"] = True
    return value


def _tc(line, name, fn, *args):
    shown = tuple(_snap(a) for a in args)      # what the action was given, before it changes it
    result = fn(*args)
    _T[line] = ("call", name, shown, _snap(result))
    known = _ACT.get(name)
    if known:
        _T[known[0]] = ("params", known[1], shown)
    _W_STATE["dirty"] = True
    return result


def _tg(line, fn, *args):
    result = fn(*args, line)
    _T[line] = ("gfx", tuple(_snap(a) for a in args), _snap(result))
    _W_STATE["dirty"] = True
    return result


def _wflush():
    if not _W_PATH or not _W_STATE["dirty"]:
        return
    _W_STATE["dirty"] = False
    _W_STATE["seq"] += 1
    try:
        rows = [[name, _wfmt(v), line] for name, (v, line) in list(_W.items())]
        lines = {}
        for line, entry in list(_T.items()):
            text = _wnote(entry)
            lines[str(line)] = text if len(text) <= 80 else text[:77] + "..."
        tmp = _W_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump({"seq": _W_STATE["seq"], "vars": rows, "lines": lines}, f)
        _wos.replace(tmp, _W_PATH)
    except Exception:
        pass


def _wloop():
    while True:
        _wtime.sleep(0.15)
        _wflush()


if _W_PATH:
    _wthreading.Thread(target=_wloop, daemon=True).start()
    import atexit as _watexit
    _watexit.register(_wflush)
"""
